// Dovetail joint between two boards end to end: part A carries the tail, part B the
// socket. Each part is one closed outline extruded, so the fit is exact by construction;
// the socket is the tail grown by the clearance C on every face.
// The tail is W wide at the joint line x = Lb and widens by Depth / Slope on each side.
let y0 = Wb / 2.0;
let spread = Depth / Slope;
let r = W / 2.0;
let t = r + spread;
let len = (Depth * Depth + spread * spread).sqrt();
// a slanted side moved out by C along its normal meets the joint line C·len/Depth further out
let sr = r + C * len / Depth;
let st = sr + spread * (Depth + C) / Depth;
let a = [point(0, 0, 0), point(Lb, 0, 0), point(Lb, y0 - r, 0), point(Lb + Depth, y0 - t, 0),
         point(Lb + Depth, y0 + t, 0), point(Lb, y0 + r, 0), point(Lb, Wb, 0), point(0, Wb, 0)];
let b = [point(Lb, 0, 0), point(2 * Lb, 0, 0), point(2 * Lb, Wb, 0), point(Lb, Wb, 0),
         point(Lb, y0 + sr, 0), point(Lb + Depth + C, y0 + st, 0),
         point(Lb + Depth + C, y0 - st, 0), point(Lb, y0 - sr, 0)];
part_a = extrude(polyline(a, true), vec(0, 0, T));
part_b = extrude(polyline(b, true), vec(0, 0, T));
